package com.glassbox.checkers.domain; import com.glassbox.chess.domain.Position;
public final class CheckersMove{private final Position from,to,capturedPos;private final CheckersPiece movedPiece,capturedPiece;private final boolean wasKingBefore;public CheckersMove(Position f,Position t,CheckersPiece m,CheckersPiece c,Position cp,boolean king){from=f;to=t;movedPiece=m;capturedPiece=c;capturedPos=cp;wasKingBefore=king;}public Position getFrom(){return from;}public Position getTo(){return to;}public CheckersPiece getMovedPiece(){return movedPiece;}public CheckersPiece getCapturedPiece(){return capturedPiece;}public Position getCapturedPos(){return capturedPos;}public boolean wasKingBefore(){return wasKingBefore;}}
